def rearange_string(s):
    # Count occurrences of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check if any character appears more than twice
    for count in char_count.values():
        if count > 2:
            return False

    # Try to arrange the string
    sorted_chars = sorted(char_count.items(), key=lambda x: x[1], reverse=True)
    result = []

    while sorted_chars:
        first_char, first_count = sorted_chars.pop(0)
        second_char, second_count = sorted_chars.pop(0) if sorted_chars else ('', 0)

        result.append(first_char)
        result.append(second_char)

        if first_count - 1 > 0:
            sorted_chars.append((first_char, first_count - 1))
        if second_count - 1 > 0:
            sorted_chars.append((second_char, second_count - 1))

    return ''.join(result)
