def next_smallest_palindrome(n):
    # Convert the number to string to easily manipulate digits
    num_str = str(n)

    # Find the length of the number
    length = len(num_str)

    # Check if the number is already a palindrome
    if num_str == num_str[::-1]:
        # If it's a palindrome, increment the last digit
        for i in range(length - 2, -1, -1):
            if num_str[i] < '9':
                num_str[i] = chr(ord(num_str[i]) + 1)
                break
        else:
            # If all digits are 9, prepend a 1 and make the rest 0s
            return int('1' + '0' * (length - 1))

    # If not a palindrome, find the next palindrome by moving from the end towards the beginning
    for i in range(length - 1, -1, -1):
        if num_str[i] != '9':
            num_str[i] = chr(ord(num_str[i]) + 1)
            break

    # Fill the remaining digits with 9s
    num_str = num_str[:i+1] + '9' * (length - i - 1)

    return int(num_str)

# Test the function
